70	    /**
71	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
72	     * domain containing at least one dot, with no whitespace in any part.
73	     */
74	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization. Keys are the
78	     * upper-cased abbreviation as it appears as a whole whitespace-delimited token; values are the
79	     * expanded form it is replaced with.
80	     */
81	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
82	        "ST", "STREET",
83	        "RD", "ROAD",
84	        "AVE", "AVENUE");
