86	    /**
87	     * The maximum number of owners a single city may contain. Once a city holds this many owners it
88	     * is at capacity and cannot take any more.
89	     */
90	    private static final int CITY_CAPACITY = 50;
91	
92	    /**
93	     * The maximum number of owners that may be registered in a single day. Once this many owners
94	     * already carry today's {@code registrationDate}, the day's quota is exhausted and no further
95	     * owners can be created that day.
96	     */
97	    private static final int DAILY_OWNER_LIMIT = 100;
