174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
185	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
186	        this.clinicService.saveOwner(currentOwner);
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
188	    }
