267	    /**
268	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
269	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
270	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
271	     *
272	     * @param ownerFieldsDto the submitted owner fields
273	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
274	     *                                     name of every offending field
275	     */
276	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
277	        List<String> missingFields = new ArrayList<>();
278	        if (isBlank(ownerFieldsDto.getFirstName())) {
279	            missingFields.add("firstName");
280	        }
281	        if (isBlank(ownerFieldsDto.getLastName())) {
282	            missingFields.add("lastName");
283	        }
284	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
285	            missingFields.add("address");
286	        }
287	        if (isBlank(ownerFieldsDto.getCity())) {
288	            missingFields.add("city");
289	        }
290	        if (isBlank(ownerFieldsDto.getTelephone())) {
291	            missingFields.add("telephone");
292	        }
293	        if (!missingFields.isEmpty()) {
294	            throw new InvalidOwnerFieldsException(missingFields);
295	        }
296	    }
297	
298	    private boolean isBlank(String value) {
299	        return value == null || value.isBlank();
300	    }
301	
302	    /**
303	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
304	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
305	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
306	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
307	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
308	     *
309	     * @param telephone the raw telephone value submitted by the client
310	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
311	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
312	     *                                     400 response
313	     */
314	    private String normalizeTelephone(String telephone) {
315	        String e164 = toE164(telephone);
316	        if (e164 == null) {
317	            throw new InvalidOwnerFieldsException(List.of("telephone"));
318	        }
319	        return e164;
320	    }
321	
322	    /**
323	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
324	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
325	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
326	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
327	     *
328	     * @param telephone the raw telephone value, possibly {@code null}
329	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
330	     */
331	    private String toE164(String telephone) {
332	        if (telephone == null) {
333	            return null;
334	        }
335	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
336	        boolean hasPlus = cleaned.startsWith("+");
337	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
338	        String nationalSignificant = hasPlus
339	            ? digits
340	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
341	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
342	            return null;
343	        }
344	        return "+" + nationalSignificant;
345	    }
346	
347	    /**
348	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
349	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
350	     * returned value is that address lower-cased.
351	     *
352	     * @param email the raw email value submitted by the client, or {@code null} if omitted
353	     * @return the lower-cased email, or {@code null} if none was supplied
354	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
355	     *                                     yielding a 400 response
356	     */
357	    private String normalizeEmail(String email) {
358	        if (email == null) {
359	            return null;
360	        }
361	        if (!EMAIL_PATTERN.matcher(email).matches()) {
362	            throw new InvalidOwnerFieldsException(List.of("email"));
363	        }
364	        return email.toLowerCase(Locale.ROOT);
365	    }
366	
367	    /**
368	     * Counts the existing owners that, before this create, already share the given first name and
369	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
370	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
371	     * been saved yet, so it is never included in the count.
372	     *
373	     * @param firstName the first name of the owner being created
374	     * @param lastName  the last name of the owner being created
375	     * @return the number of existing owners sharing both names
376	     */
377	    private int countNamesakes(String firstName, String lastName) {
378	        String normalizedFirstName = normalizeForComparison(firstName);
379	        String normalizedLastName = normalizeForComparison(lastName);
380	        return (int) this.clinicService.findAllOwners().stream()
381	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
382	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
383	            .count();
384	    }
385	
386	    /**
387	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
388	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
389	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
390	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
391	     *
392	     * @param city     the owner's city
393	     * @param lastName the owner's last name
394	     * @return the formatted customer code
395	     */
396	    private String generateCustomerCode(String city, String lastName) {
397	        String city3 = first3Letters(city);
398	        String last3 = first3Letters(lastName);
399	        int sequence = countOwnersInCity(city) + 1;
400	        return String.format("%s-%s-%04d", city3, last3, sequence);
401	    }
402	
403	    /**
404	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
405	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
406	     *
407	     * @param value the value to abbreviate
408	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
409	     */
410	    private String first3Letters(String value) {
411	        String letters = value.replaceAll("[^\\p{L}]", "");
412	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
413	    }
414	
415	    /**
416	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
417	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
418	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
419	     * has not been saved yet, so it is never included in the count.
420	     *
421	     * @param city the city of the owner being created
422	     * @return the number of existing owners in that city
423	     */
424	    private int countOwnersInCity(String city) {
425	        String normalizedCity = normalizeForComparison(city);
426	        return (int) this.clinicService.findAllOwners().stream()
427	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
428	            .count();
429	    }
430	
431	    /**
432	     * Rejects creation of an owner whose city already contains the maximum number of owners
433	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
434	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
435	     *
436	     * @param city the city of the owner being created
437	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
438	     *                                      owners, yielding a 409 Conflict response
439	     */
440	    private void rejectCityAtCapacity(String city) {
441	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
442	            throw new OwnerCityAtCapacityException(city);
443	        }
444	    }
445	
446	    /**
447	     * Rejects creation of an owner once the given business day has already reached its daily quota
448	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
449	     * being that day — the adjusted business day the owner being created will carry — so the quota
450	     * applies per business day. The owner being created has not been saved yet, so it is never
451	     * included in the count.
452	     *
453	     * @param registrationDate the adjusted business-day registration date of the owner being created
454	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
455	     *                                         carry that registration date, yielding a
456	     *                                         429 Too Many Requests response
457	     */
458	    private void rejectDailyLimitReached(LocalDate registrationDate) {
459	        long createdThatDay = this.clinicService.findAllOwners().stream()
460	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
461	            .count();
462	        if (createdThatDay >= DAILY_OWNER_LIMIT) {
463	            throw new DailyOwnerLimitReachedException(registrationDate);
464	        }
465	    }
466	
467	    /**
468	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
469	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
470	     * applies to the effective registration date whether it was supplied in the request or defaulted
471	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
472	     * feeds every value derived from it (such as the membership number's year segment and the daily
473	     * create-limit's per-day bucket).
474	     *
475	     * @param date the effective registration date, supplied or defaulted
476	     * @return the same date when it is a weekday, otherwise the next Monday
477	     */
478	    private LocalDate toBusinessDay(LocalDate date) {
479	        LocalDate adjusted = date;
480	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
481	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
482	            adjusted = adjusted.plusDays(1);
483	        }
484	        return adjusted;
485	    }
486	
487	    /**
488	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
489	     * telephones are converted to E.164 here as well so the comparison is independent of the format
490	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
491	     * ignored rather than matched.
492	     *
493	     * @param telephone the E.164 telephone of the owner being created
494	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
495	     *                                          yielding a 409 Conflict response
496	     */
497	    private void rejectDuplicateTelephone(String telephone) {
498	        boolean inUse = this.clinicService.findAllOwners().stream()
499	            .map(Owner::getTelephone)
500	            .map(this::toE164)
501	            .anyMatch(telephone::equals);
502	        if (inUse) {
503	            throw new DuplicateOwnerTelephoneException(telephone);
504	        }
505	    }
506	
507	    /**
508	     * Rejects creation of an owner whose last name and address both match an existing owner's,
509	     * which marks them as belonging to the same household. Both the last name and the address are
510	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
511	     * that differ only in letter case or spacing are still treated as a match.
512	     *
513	     * @param lastName the last name of the owner being created
514	     * @param address  the address of the owner being created
515	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
516	     *                                          address, yielding a 409 Conflict response
517	     */
518	    private void rejectDuplicateHousehold(String lastName, String address) {
519	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
520	            throw new DuplicateOwnerHouseholdException(lastName, address);
521	        }
522	    }
523	
524	    /**
525	     * Finds every existing owner belonging to the household identified by the given last name and
526	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
527	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
528	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
529	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
530	     * and {@link #assignHousehold}.
531	     *
532	     * @param lastName the last name of the owner being created
533	     * @param address  the address of the owner being created
534	     * @return the existing owners in that household, or an empty list if there are none
535	     */
536	    private List<Owner> findHouseholdMembers(String lastName, String address) {
537	        String normalizedLastName = normalizeForComparison(lastName);
538	        String normalizedAddress = normalizeAddress(address);
539	        return this.clinicService.findAllOwners().stream()
540	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
541	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
542	            .toList();
543	    }
544	
545	    /**
546	     * Enrolls a newly created owner into the household of any existing owner that shares its last
547	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
548	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
549	     * whitespace. When at least one such owner already exists, every member of the household — the
550	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
551	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
552	     * and address is created and back-filled onto the existing members. When no owner yet lives at
553	     * that address under the same last name no identifier is assigned and the owner is created alone.
554	     *
555	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
556	     * @param lastName the last name of the owner being created
557	     * @param address  the address of the owner being created
558	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
559	     */
560	    private String assignHousehold(Owner newOwner, String lastName, String address) {
561	        List<Owner> members = findHouseholdMembers(lastName, address);
562	        if (members.isEmpty()) {
563	            return null;
564	        }
565	        String householdId = members.stream()
566	            .map(Owner::getHouseholdId)
567	            .filter(existing -> existing != null && !existing.isBlank())
568	            .findFirst()
569	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
570	        for (Owner member : members) {
571	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
572	                member.setHouseholdId(householdId);
573	                this.clinicService.saveOwner(member);
574	            }
575	        }
576	        newOwner.setHouseholdId(householdId);
577	        return householdId;
578	    }
579	
580	    /**
581	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
582	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
583	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
584	     * same identifier, so members of one household share a single value.
585	     *
586	     * @param normalizedLastName the household's last name, already normalized for comparison
587	     * @param normalizedAddress  the household's address, already normalized for comparison
588	     * @return the derived household identifier
589	     */
590	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
591	        try {
592	            byte[] digest = MessageDigest.getInstance("SHA-256")
593	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
594	            StringBuilder hex = new StringBuilder(digest.length * 2);
595	            for (byte b : digest) {
596	                hex.append(String.format("%02x", b));
597	            }
598	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
599	        } catch (NoSuchAlgorithmException e) {
600	            throw new IllegalStateException("SHA-256 algorithm not available", e);
601	        }
602	    }
603	
604	    /**
605	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
606	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
607	     * the result is lower-cased.
608	     *
609	     * @param value the value to normalize, possibly {@code null}
610	     * @return the normalized value, or an empty string if {@code value} is {@code null}
611	     */
612	    private String normalizeForComparison(String value) {
613	        if (value == null) {
614	            return "";
615	        }
616	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
617	    }
618	
619	    /**
620	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
621	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
622	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
623	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
624	     * This normalized value is what gets stored and returned, and it is the form every address
625	     * comparison (household duplicate detection and the shared household id) uses.
626	     *
627	     * @param address the raw address value submitted by the client, possibly {@code null}
628	     * @return the normalized address, or an empty string if {@code address} is {@code null}
629	     */
630	    private String normalizeAddress(String address) {
631	        if (address == null) {
632	            return "";
633	        }
634	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
635	        if (collapsed.isEmpty()) {
636	            return collapsed;
637	        }
638	        String[] tokens = collapsed.split(" ");
639	        StringBuilder normalized = new StringBuilder(collapsed.length());
640	        for (int i = 0; i < tokens.length; i++) {
641	            if (i > 0) {
642	                normalized.append(' ');
643	            }
644	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
645	        }
646	        return normalized.toString();
647	    }
648	}
